insert into public.site_profile(id,data) values(true,'{"name":"쪼삼이","short":"장난기 많은데 정 붙으면 엄청 편한 타입","bio":"초면에도 잘 놀아요, 다만 오냐오냐해줘야합니다…","image":"/assets/profile.webp","alt":"쪼삼이 대표 이미지","channel":"https://www.sooplive.com/station/bomyangul","fields":[{"id":"debut","label":"방송 시작","value":"","binding":"debut","visible":true},{"id":"birthday","label":"생일","value":"","binding":"birthday","visible":true},{"id":"height","label":"키","value":"168cm","visible":true},{"id":"mbti","label":"MBTI","value":"INFP","visible":true},{"id":"likes","label":"좋아해요","value":"놀리는거, 디저트류, 방송장비, 예쁜 언니야들, 사랑받기","visible":true},{"id":"dislikes","label":"싫어해요","value":"놀림받는거, 공포게임, 똥겜, 질투유발하는 무언가, 벌레","visible":true},{"id":"wish","label":"하고싶어요","value":"모두에게 사랑받는 사랑둥이 막내가 되고싶어요!","visible":true},{"id":"fan","label":"팬덤명","value":"미정","visible":true}]}'::jsonb) on conflict do nothing;
